    'The app-relative path MCP clients connect to, such as `/mcp`.' => 'Y llwybr, o’i gymharu â’r ap, y mae cleientiaid MCP yn cysylltu ag ef, fel `/mcp`.',
    'The app-relative path public MCP clients connect to, such as `/mcp`.' => 'Y llwybr, o’i gymharu â’r ap, y mae cleientiaid MCP cyhoeddus yn cysylltu ag ef, fel `/mcp`.',
    'The app-relative path to give MCP clients that sign in with OAuth. It always requires an access token, so clients can discover how to sign in.' => 'Y llwybr, o’i gymharu â’r ap, i’w roi i gleientiaid MCP sy’n mewngofnodi gydag OAuth. Mae bob amser angen tocyn mynediad arno, fel bod cleientiaid yn gallu darganfod sut i fewngofnodi.',
    'The authenticated server uses this endpoint too. Requests without an access token go to the public server, so MCP clients can’t discover how to sign in at this endpoint.' => 'Mae’r gweinydd dilysedig yn defnyddio’r pwynt terfyn hwn hefyd. Mae ceisiadau heb docyn mynediad yn mynd i’r gweinydd cyhoeddus, felly ni all cleientiaid MCP ddarganfod sut i fewngofnodi yn y pwynt terfyn hwn.',
