    'This URL is an MCP server for AI assistants, not a web page. Add it to your assistant to work with this site’s content and settings in plain language.' => 'Gweinydd MCP ar gyfer cynorthwywyr AI yw’r URL hwn, nid tudalen we. Ychwanegwch ef at eich cynorthwyydd i weithio gyda chynnwys a gosodiadau’r wefan hon mewn iaith bob dydd.',
    'This application will be able to:' => 'Bydd y rhaglen hon yn gallu:',
