    'This date is for planning only. The release will not publish until it is explicitly scheduled.' => 'Ar gyfer cynllunio’n unig y mae’r dyddiad hwn. Ni fydd y rhyddhad yn cael ei gyhoeddi nes iddo gael ei amserlennu’n benodol.',
    'This disk has been reserved for temporary asset uploads. Please choose a different one for your volume.' => 'Mae’r ddisg hon wedi’i neilltuo ar gyfer llwytho asedau i fyny dros dro. Dewiswch un arall ar gyfer eich cyfrol.',
