    'This draft belongs to “{name}”. Saved changes will be included when the release publishes.' => 'Mae’r drafft hwn yn perthyn i “{name}”. Bydd newidiadau a gedwir yn cael eu cynnwys pan fydd y rhyddhad yn cael ei gyhoeddi.',
