    'The following content is for preview only.' => 'Mae’r cynnwys canlynol ar gyfer rhagolwg yn unig.',
    'The following licensing {total, plural, =1{issue} other{issues}} can be resolved with a single purchase on Craft Console:' => 'Gellir datrys y {total, plural, =1{mater} other{materion}} trwyddedu canlynol gydag un pryniant ar Craft Console:',
    'The following {items} could not be found or are empty. Should they be deleted from the index?' => 'Nid oedd modd dod o hyd i’r {items} canlynol, neu maen nhw’n wag. A ddylid eu dileu o’r mynegai?',
