    'The image format that transformed images should use.' => 'Y fformat delwedd y dylai delweddau wedi’u trawsffurfio ei ddefnyddio.',
    'The image format “{format}” is not supported.' => 'Nid yw’r fformat delwedd “{format}” yn cael ei gefnogi.',
