    'The loaded project config has more recent changes than your project config YAML files.' => 'Mae gan ffurfweddiad y prosiect a lwythwyd newidiadau mwy diweddar na ffeiliau YAML ffurfweddiad eich prosiect.',
    'The locale that should be used for date and number formatting.' => 'Y locale y dylid ei ddefnyddio ar gyfer fformatio dyddiadau a rhifau.',
    'The location where assets can be selected from.' => 'Y lleoliad lle gellir dewis asedau ohono.',
    'The maximum length (in bytes) the field can hold.' => 'Yr hyd mwyaf (mewn beitiau) y gall y maes ei ddal.',
    'The maximum number of authors that entries in this section can have.' => 'Y nifer fwyaf o awduron y gall cofnodion yn yr adran hon eu cael.',
