    'The minimum number of {type} the field is allowed to have.' => 'Y nifer leiaf o {type} y caniateir i’r maes eu cael.',
    'The number of minutes that timepicker options should be incremented by. (Authors can enter a specific time manually.)' => 'Nifer y munudau y dylai opsiynau’r dewisydd amser gynyddu. (Gall awduron roi amser penodol â llaw.)',
    'The number of seconds that the Retry-After HTTP header should be set to for maintenance mode responses.' => 'Nifer yr eiliadau y dylid gosod y pennyn HTTP Retry-After iddo ar gyfer ymatebion modd cynnal a chadw.',
    'The path can contain variables like `{slug}` or `{author.username}`.' => 'Gall y llwybr gynnwys newidynnau fel `{slug}` neu `{author.username}`.',
    'The path to a template file within your `templates/` folder.' => 'Y llwybr i ffeil templed yn eich ffolder `templates/`.',
    'The plugin was removed successfully.' => 'Tynnwyd yr ategyn yn llwyddiannus.',
    'The posted condition config is invalid.' => 'Mae ffurfweddiad yr amod a anfonwyd yn annilys.',
