    'The selected {type} could not be found.' => 'Nid oedd modd dod o hyd i’r {type} a ddewiswyd.',
    'The server doesn’t meet Craft’s new requirements:' => 'Nid yw’r gweinydd yn bodloni gofynion newydd Craft:',
    'The subpath cannot overlap with any other volumes sharing the same filesystem.' => 'Ni all yr is-lwybr orgyffwrdd ag unrhyw gyfrolau eraill sy’n rhannu’r un system ffeiliau.',
    'The template Craft CMS will use for HTML emails' => 'Y templed y bydd Craft CMS yn ei ddefnyddio ar gyfer negeseuon e-bost HTML',
    'The template Craft CMS will use for HTML emails. Leave blank to use the default template.' => 'Y templed y bydd Craft CMS yn ei ddefnyddio ar gyfer negeseuon e-bost HTML. Gadewch yn wag i ddefnyddio’r templed rhagosodedig.',
    'The template receives `element` and `static` variables. Its output is sanitized and displayed as non-interactive content; form controls, scripts, and registered assets are not supported.' => 'Mae’r templed yn derbyn newidynnau `element` a `static`. Mae ei allbwn yn cael ei lanweithio a’i ddangos fel cynnwys anrhyngweithiol; nid yw rheolyddion ffurflen, sgriptiau ac asedau cofrestredig yn cael eu cefnogi.',
    'The template will be rendered with an `element` variable.' => 'Bydd y templed yn cael ei rendro gyda newidyn `element`.',
    'The text label for the entry creation button.' => 'Label testun y botwm creu cofnod.',
