    'The values are matched inclusively.' => 'Mae’r gwerthoedd yn cael eu paru’n gynhwysol.',
    'The volume where pasted or dropped files should be uploaded.' => 'Y gyfrol lle dylid llwytho i fyny ffeiliau sy’n cael eu gludo neu eu gollwng.',
    'The volumes that should be available when selecting assets.' => 'Y cyfrolau a ddylai fod ar gael wrth ddewis asedau.',
    'The {attribute} field must be a string or array.' => 'Rhaid i’r maes {attribute} fod yn llinyn neu’n arae.',
    'The {attribute} field must contain a `class` value.' => 'Rhaid i’r maes {attribute} gynnwys gwerth `class`.',
    'The {field} field’s {setting} setting has an invalid subpath (“{subpath}”).' => 'Mae gan osodiad {setting} y maes {field} is-lwybr annilys (“{subpath}”).',
    'The {field} field’s {setting} setting is set to an invalid volume.' => 'Mae gosodiad {setting} y maes {field} wedi’i osod i gyfrol annilys.',
