    'The {name} license is invalid.' => 'Mae’r drwydded {name} yn annilys.',
    'The {numEntries, plural, =1{entry} other {entries}} will be updated once the {numUsers, plural, =1{user is} other{users are}} deleted.' => 'Bydd y {numEntries, plural, =1{cofnod yn cael ei ddiweddaru} other {cofnodion yn cael eu diweddaru}} unwaith y bydd y {numUsers, plural, =1{defnyddiwr wedi’i ddileu} other{defnyddwyr wedi’u dileu}}.',
    'The {numRelations, plural, =1{relation} other {relations}} will be removed once the {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} deleted.' => 'Bydd y {numRelations, plural, =1{berthynas yn cael ei thynnu} other {perthnasoedd yn cael eu tynnu}} unwaith y bydd y {numTargets, plural, =1{{targetTypeSingular} wedi’i ddileu} other{{targetTypePlural} wedi’u dileu}}.',
    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} referenced by fields in {numSources, number} other {numSources, plural, =1{element} other{elements}}.' => 'Mae meysydd mewn {numSources, number} {numSources, plural, =1{elfen} other{elfen}} arall yn cyfeirio at y {numTargets, plural, =1{{targetTypeSingular}} other{{targetTypePlural}}}.',
    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} related by {numRelations, number} other {numRelations, plural, =1{{sourceTypeSingular}} other{{sourceTypePlural}}}.' => 'Mae {numRelations, number} {numRelations, plural, =1{{sourceTypeSingular}} other{{sourceTypePlural}}} arall yn perthyn i’r {numTargets, plural, =1{{targetTypeSingular}} other{{targetTypePlural}}}.',
    'The {type} is invalid.' => 'Mae’r {type} yn annilys.',
