    'Where do you want to store user photos? Note that the subfolder path can contain variables like {username}.' => 'Ble ydych chi am storio lluniau defnyddwyr? Sylwch y gall llwybr yr is-ffolder gynnwys newidynnau fel {username}.',
    'Where new {type} should be placed by default in the field.' => 'Ble y dylid gosod {type} newydd yn ddiofyn yn y maes.',
    'Where new {type} should be placed by default in the structure.' => 'Ble y dylid gosod {type} newydd yn ddiofyn yn y strwythur.',
    'Where transforms should be stored on the filesystem.' => 'Ble y dylid storio trawsffurfiadau ar y system ffeiliau.',
    'Whether HTML should be encoded before rendering the Markdown.' => 'A ddylid amgodio HTML cyn rendro’r Markdown.',
    'Whether authors should be able to choose which time zone the time is in.' => 'A ddylai awduron allu dewis ym mha gylchfa amser y mae’r amser.',
    'Whether authors should be able to upload files directly to the field, rather than requiring them to select/upload assets via the selection modal.' => 'A ddylai awduron allu llwytho ffeiliau i fyny’n uniongyrchol i’r maes, yn hytrach na gorfod dewis/llwytho asedau i fyny drwy’r ffenestr ddewis.',
    'Whether buttons should only show their icons, hiding their text labels.' => 'A ddylai botymau ddangos eu heiconau yn unig, gan guddio eu labeli testun.',
    'Whether card views which include this field should show the custom ON/OFF labels, rather than the field name.' => 'A ddylai golygon cerdyn sy’n cynnwys y maes hwn ddangos y labeli YMLAEN/I FFWRDD personol, yn hytrach nag enw’r maes.',
    'Whether custom fields should be validated during public registration.' => 'A ddylid dilysu meysydd personol wrth gofrestru’n gyhoeddus.',
    'Whether the editor should show character, word, and line counts.' => 'A ddylai’r golygydd ddangos cyfrif nodau, geiriau a llinellau.',
    'Whether the editor toolbar should be visible.' => 'A ddylai bar offer y golygydd fod yn weladwy.',
    'Whether the element index should allow viewing nested {type} in a table.' => 'A ddylai’r mynegai elfennau ganiatáu gweld {type} nythog mewn tabl.',
    'Whether the field should only render inline Markdown, without wrapping paragraphs.' => 'A ddylai’r maes rendro Markdown mewnlin yn unig, heb lapio paragraffau.',
    'Whether the number of elements in this source should be shown beside it in the navigation.' => 'A ddylid dangos nifer yr elfennau yn y ffynhonnell hon wrth ei hymyl yn y llywio.',
    'Whether the site menu should be shown for {type} selection modals.' => 'A ddylid dangos dewislen y gwefannau ar gyfer ffenestri dewis {type}.',
    'Whether the structure of the related {type} should be maintained.' => 'A ddylid cynnal strwythur y {type} cysylltiedig.',
    'Whether the table rows should be restricted to those defined by the “Default Values” setting.' => 'A ddylid cyfyngu rhesi’r tabl i’r rhai a ddiffinnir gan y gosodiad “Gwerthoedd Rhagosodedig”.',
    'Whether this can be dismissed by a user and not shown again.' => 'A all defnyddiwr gau hwn fel na fydd yn cael ei ddangos eto.',
    'Whether to show entries that the user doesn’t have permission to view, per the “View other users’ entries” permission.' => 'A ddylid dangos cofnodion nad oes gan y defnyddiwr ganiatâd i’w gweld, yn unol â’r caniatâd “Gweld cofnodion defnyddwyr eraill”.',
    'Whether to show files that the user doesn’t have permission to view, per the “View files uploaded by other users” permission.' => 'A ddylid dangos ffeiliau nad oes gan y defnyddiwr ganiatâd i’w gweld, yn unol â’r caniatâd “Gweld ffeiliau a lwythwyd i fyny gan ddefnyddwyr eraill”.',
    'Whether to show sections that the user doesn’t have permission to view.' => 'A ddylid dangos adrannau nad oes gan y defnyddiwr ganiatâd i’w gweld.',
    'Whether to show volumes that the user doesn’t have permission to view.' => 'A ddylid dangos cyfrolau nad oes gan y defnyddiwr ganiatâd i’w gweld.',
    'Whether validation errors on the related {type} should prevent the source element from being saved.' => 'A ddylai gwallau dilysu ar y {type} cysylltiedig atal yr elfen ffynhonnell rhag cael ei chadw.',
    'Whether {type} elements should be allowed to relate to themselves.' => 'A ddylid caniatáu i elfennau {type} berthyn iddynt eu hunain.',
